<x-layouts.app><h1>Today's Attendance · {{ $class->name }}</h1><p class="muted">{{ $session->isLocked() ? 'Attendance locked at 9:00 AM.' : 'Attendance can be edited until 9:00 AM.' }}</p><form method="post" action="{{route('teacher.attendance.save',$class)}}">@csrf @method('PUT')<div class="card"><input class="no-print" placeholder="Search students" oninput="document.querySelectorAll('[data-student]').forEach(r=>r.hidden=!r.innerText.toLowerCase().includes(this.value.toLowerCase()))"><table><thead><tr><th>Student</th><th>Status</th></tr></thead><tbody>@foreach($class->students()->orderBy('student_id')->get() as $student)@php($record=$session->records()->where('student_id',$student->id)->first())@php($recordIndex=$loop->index)<tr data-student><td><strong>{{ $student->full_name }}</strong><br><span class="muted">{{ $student->student_id }}</span></td><td>@foreach(['present'=>'Present','absent'=>'Absent','late'=>'Late'] as $value=>$label)<label style="display:inline-block;margin-right:8px"><input {{ $session->isLocked()?'disabled':'' }} style="width:auto" type="radio" name="records[{{$recordIndex}}][status]" value="{{$value}}" @checked(($record?->status ?? 'present')===$value)>{{$label}}</label>@endforeach<input type="hidden" name="records[{{$recordIndex}}][student_id]" value="{{$student->id}}"></td></tr>@endforeach</tbody></table></div>@if(!$session->isLocked())<button>Save attendance</button>@endif</form>@if(!$session->isLocked())<form class="no-print" method="post" action="{{route('teacher.attendance.submit',$session)}}" onsubmit="return confirm('Confirm attendance submission?')">@csrf<button class="alt">Confirm Attendance</button></form>@endif</x-layouts.app>
